+import type { Entry, Log } from "./store";
+
+/** Entries compacted between two yields. */
+export const SLICE = 200;
+
+export interface Compaction {
+  /** Resolves when the whole log is compacted. */
+  done: Promise<void>;
+  cancel(): void;
+}
+
+/** Compact `log` a slice at a time, yielding to `idle` between slices. */
+export function compactInSlices(log: Log, idle: (run: () => void) => void): Compaction {
+  let cancelled = false;
+  let at = 0;
+  const latest = new Map<string, Entry>();
+  const done = new Promise<void>((resolve) => {
+    const slice = () => {
+      if (cancelled) return resolve();
+      const end = Math.min(at + SLICE, log.entries.length);
+      for (; at < end; at++) {
+        const entry = log.entries[at]!;
+        latest.set(entry.key, entry);
+      }
+      if (at < log.entries.length) return idle(slice);
+      log.replace([...latest.values()]);
+      resolve();
+    };
+    idle(slice);
+  });
+  return {
+    done,
+    cancel() {
+      cancelled = true;
+    },
+  };
+}

