+/** An observed-remove set: an add survives unless a remove has seen it. */
+export interface OrSet {
+  adds: Map<string, Set<string>>;
+  removes: Set<string>;
+}
+
+export const empty = (): OrSet => ({ adds: new Map(), removes: new Set() });
+
+export function add(set: OrSet, value: string, dot: string) {
+  const dots = set.adds.get(value) ?? new Set();
+  dots.add(dot);
+  set.adds.set(value, dots);
+}
+
+export function remove(set: OrSet, value: string) {
+  for (const dot of set.adds.get(value) ?? []) set.removes.add(dot);
+}
+
+export function values(set: OrSet): string[] {
+  return [...set.adds].filter(([, dots]) => [...dots].some((d) => !set.removes.has(d))).map(([v]) => v);
+}
+
+export function merge(a: OrSet, b: OrSet): OrSet {
+  const out = empty();
+  for (const source of [a, b]) {
+    for (const [value, dots] of source.adds) for (const dot of dots) add(out, value, dot);
+    for (const dot of source.removes) out.removes.add(dot);
+  }
+  return out;
+}

