export { tidepool } from "./tidepool";
export type { Store, Entry } from "./log/store";
export type { MergeRule } from "./merge";
export { WIRE_VERSION } from "./wire";

import { Store } from "./log/store";
import { connect } from "./sync";

export interface Database {
  store<T = unknown>(name: string): Store<T>;
  sync(url: string): () => void;
  close(): void;
}

export const tidepool = {
  async open(name: string): Promise<Database> {
    const stores = new Map<string, Store>();
    let stop: (() => void) | null = null;
    return {
      store(storeName) {
        let store = stores.get(storeName);
        if (!store) stores.set(storeName, (store = new Store({ name: `${name}/${storeName}` })));
        return store as Store<never>;
      },
      sync(url) {
        stop?.();
        stop = connect(url, [...stores.values()]);
        return () => stop?.();
      },
      close() {
        stop?.();
        stores.clear();
      },
    };
  },
};

import { encode } from "../codec";

const MAX_BYTES = 2 * 1024 * 1024;

export interface Entry {
  key: string;
  value: unknown;
  /** Lamport time of the write. */
  at: number;
  device?: string;
}

export interface Log {
  entries: Entry[];
  replace(entries: Entry[]): void;
}

export class Store<T = unknown> {
  private log: Log;
  private bytes = 0;
  private watchers = new Set<(entry: Entry) => void>();

  constructor(private options: { name?: string; idle?: (run: () => void) => void } = {}) {
    const entries: Entry[] = [];
    this.log = { entries, replace: (next) => entries.splice(0, entries.length, ...next) };
  }

  get(key: string): T | undefined {
    for (let i = this.log.entries.length - 1; i >= 0; i--) {
      const entry = this.log.entries[i]!;
      if (entry.key === key) return entry.value as T;
    }
    return undefined;
  }

  append(entry: Entry) {
    this.log.entries.push(entry);
    this.bytes += encode(entry).length;
    for (const watch of this.watchers) watch(entry);
  }

  watch(run: (entry: Entry) => void) {
    this.watchers.add(run);
    return () => this.watchers.delete(run);
  }

  /** Keep only the newest entry for each key. */
  compact() {
    const latest = new Map<string, Entry>();
    for (const entry of this.log.entries) latest.set(entry.key, entry);
    this.log.replace([...latest.values()]);
    this.bytes = this.log.entries.reduce((n, e) => n + encode(e).length, 0);
  }

  size() {
    return new Set(this.log.entries.map((e) => e.key)).size;
  }

  get full() {
    return this.bytes > MAX_BYTES;
  }
}

