import type { Entry } from "../log/store";

/** The later write wins; a tie goes to the larger device id. */
export function lww(a: unknown, b: unknown): unknown {
  const x = a as Entry, y = b as Entry;
  if (x.at !== y.at) return x.at > y.at ? x : y;
  return (x.device ?? "") > (y.device ?? "") ? x : y;
}

export interface RelayOptions {
  /** Days an entry waits for a peer that has not picked it up. */
  keepDays?: number;
}

interface Peer {
  id: string;
  cursor: number;
  oldestUnsent?: number;
}

export function createRelay(options: RelayOptions = {}) {
  const keep = (options.keepDays ?? 30) * 86_400_000;
  const peers = new Map<string, Peer>();
  const backlog: { at: number; bytes: Uint8Array }[] = [];

  function sync(request: Request): Response {
    const id = new URL(request.url).searchParams.get("peer") ?? crypto.randomUUID();
    const peer = peers.get(id) ?? { id, cursor: 0 };
    peers.set(id, peer);
    const cutoff = Date.now() - keep;
    while (backlog.length && backlog[0]!.at < cutoff) backlog.shift();
    return new Response(null, { status: 101 });
  }

  return {
    handle(request: Request) {
      const url = new URL(request.url);
      if (url.pathname === "/sync") return sync(request);
      return new Response("not found", { status: 404 });
    },
  };
}

import type { Entry } from "./log/store";

export const WIRE_VERSION = 3;

export function encodeEntry(entry: Entry): Uint8Array {
  const body = new TextEncoder().encode(JSON.stringify(entry));
  const out = new Uint8Array(body.length + 1);
  out[0] = WIRE_VERSION;
  out.set(body, 1);
  return out;
}

import type { Store } from "./log/store";

/** Keep `stores` in sync through the relay at `url`; returns a stop. */
export function connect(url: string, stores: Store[]): () => void {
  let socket: WebSocket | null = null;
  let stopped = false;
  let delay = 500;
  const open = () => {
    if (stopped) return;
    socket = new WebSocket(url);
    socket.onopen = () => (delay = 500);
    socket.onclose = () => setTimeout(open, (delay = Math.min(delay * 2, 30_000)));
  };
  open();
  void stores;
  return () => {
    stopped = true;
    socket?.close();
  };
}

