use quick_xml::events::Event;
use quick_xml::Reader;

#[derive(Clone, Copy)]
pub struct Point {
    pub lat: f64,
    pub lon: f64,
    pub ele: f64,
    pub time: i64,
}

pub struct Track {
    pub name: String,
    pub points: Vec<Point>,
}

impl Track {
    pub fn km(&self) -> f64 {
        self.points.windows(2).map(|w| w[0].distance_to(&w[1])).sum::<f64>() / 1000.0
    }

    pub fn climb(&self) -> i64 {
        self.points.windows(2).map(|w| (w[1].ele - w[0].ele).max(0.0)).sum::<f64>() as i64
    }
}

impl Point {
    /// Metres along the great circle.
    pub fn distance_to(&self, other: &Point) -> f64 {
        let r = 6_371_000.0;
        let (a, b) = (self.lat.to_radians(), other.lat.to_radians());
        let dlat = b - a;
        let dlon = (other.lon - self.lon).to_radians();
        let h = (dlat / 2.0).sin().powi(2) + a.cos() * b.cos() * (dlon / 2.0).sin().powi(2);
        2.0 * r * h.sqrt().asin()
    }
}

pub fn read(path: &std::path::Path) -> Result<Track, Box<dyn std::error::Error>> {
    let mut reader = Reader::from_file(path)?;
    let mut points = Vec::new();
    let mut buf = Vec::new();
    loop {
        match reader.read_event_into(&mut buf)? {
            Event::Eof => break,
            Event::Start(e) if e.name().as_ref() == b"trkpt" => {
                let attr = |k: &[u8]| e.try_get_attribute(k).ok().flatten().map(|a| String::from_utf8_lossy(&a.value).parse().unwrap_or(0.0));
                points.push(Point { lat: attr(b"lat").unwrap_or(0.0), lon: attr(b"lon").unwrap_or(0.0), ele: 0.0, time: 0 });
            }
            _ => {}
        }
        buf.clear();
    }
    Ok(Track { name: path.file_stem().unwrap_or_default().to_string_lossy().into(), points })
}

use crate::gpx::Point;

/// The track as rows of dots, north up.
pub fn map(points: &[Point], width: usize, height: usize) -> Vec<String> {
    let mut grid = vec![vec!['.'; width]; height];
    let (min_lat, max_lat) = range(points.iter().map(|p| p.lat));
    let (min_lon, max_lon) = range(points.iter().map(|p| p.lon));
    for p in points {
        let x = scale(p.lon, min_lon, max_lon, width);
        let y = height - 1 - scale(p.lat, min_lat, max_lat, height);
        grid[y][x] = '*';
    }
    grid.into_iter().map(|row| row.into_iter().collect()).collect()
}

/// Elevation along the track, highest at the top.
pub fn elevation(points: &[Point], width: usize, height: usize) -> Vec<String> {
    let (lo, hi) = range(points.iter().map(|p| p.ele));
    let mut rows = vec![vec![' '; width]; height];
    for (i, p) in points.iter().enumerate() {
        let x = i * (width - 1) / points.len().max(2).saturating_sub(1).max(1);
        let y = height - 1 - scale(p.ele, lo, hi, height);
        rows[y][x.min(width - 1)] = '#';
    }
    rows.into_iter().map(|row| row.into_iter().collect()).collect()
}

fn range(values: impl Iterator<Item = f64>) -> (f64, f64) {
    values.fold((f64::MAX, f64::MIN), |(lo, hi), v| (lo.min(v), hi.max(v)))
}

fn scale(v: f64, lo: f64, hi: f64, cells: usize) -> usize {
    if hi <= lo { return 0; }
    (((v - lo) / (hi - lo)) * (cells - 1) as f64).round() as usize
}

