#define SPROUT_IMPLEMENTATION
#include "../sprout.h"

int main(void) {
  sp_init(320, 240, "bounce");
  sp_sprite *ball = sp_load("ball.png");
  int x = 10, y = 10, dx = 2, dy = 1;
  while (sp_frame()) {
    x += dx; y += dy;
    if (x < 0 || x > 304) dx = -dx;
    if (y < 0 || y > 224) dy = -dy;
    sp_clear(0x1d2b53);
    sp_draw(ball, x, y);
  }
  return 0;
}

